toolScript:
const sequence = [
            '#0d0d0d', // 5% Grey
            '#1a1a1a', // 10% Grey
            '#333333', // 20% Grey
            '#808080', // 50% Grey
            '#ffffff', // 100% White
            '#ff0000', // Pure Red
            '#00ff00', // Pure Green
            '#0000ff', // Pure Blue
            '#00ffff', // Cyan
            '#ff00ff', // Magenta
            '#ffff00', // Yellow
            '#000000'  // 0% Black
        ];
        let currentIndex = 0;
        let autoTestInterval = null;
        function startTest(startColor) {
            clearAutoTest(); // Halt auto-test if user takes manual control
            const overlay = document.getElementById('test-overlay');
            if (startColor) {
                currentIndex = sequence.indexOf(startColor);
                if (currentIndex === -1) {
                    currentIndex = 0;
                }
                overlay.style.background = startColor;
            }
            openOverlay(overlay);
        }
        // --- NEW: Dynamic IRE Tuner ---
        function updateIreValue() {
            const ire = document.getElementById('ire-slider').value;
            document.getElementById('ire-display').innerText = ire + '%';
        }
        function launchIreTest() {
            clearAutoTest();
            const ire = document.getElementById('ire-slider').value;
            // Calculate 8-bit RGB value based on percentage
            const rgbVal = Math.round((ire / 100) * 255);
            // Convert to Hex
            const hex = "#" + (rgbVal).toString(16).padStart(2, '0').repeat(3);
            const overlay = document.getElementById('test-overlay');
            overlay.style.background = hex;
            openOverlay(overlay);
        }
        // --- NEW: Gradient Test ---
        function startGradientTest() {
            clearAutoTest();
            const overlay = document.getElementById('test-overlay');
            overlay.style.background = 'linear-gradient(to right, #000000, #404040)';
            openOverlay(overlay);
        }
        // --- NEW: Auto-Run Diagnostic ---
        function startAutoTest() {
            const overlay = document.getElementById('test-overlay');
            // Critical diagnostic sequence
            const autoSequence = ['#0d0d0d', '#ffffff', '#ff0000', '#00ff00', '#0000ff', '#000000'];
            let autoIndex = 0;
            overlay.style.background = autoSequence[autoIndex];
            openOverlay(overlay);
            const hint = document.getElementById('overlay-hint');
            hint.innerText = "Auto-Scan Active • Tap or ESC to Exit";
            hint.style.opacity = '1';
            autoTestInterval = setInterval(() => {
                autoIndex++;
                if (autoIndex >= autoSequence.length) {
                    stopTest();
                    return;
                }
                overlay.style.background = autoSequence[autoIndex];
            }, 5000); // 5 seconds per slide
        }
        function clearAutoTest() {
            if (autoTestInterval) {
                clearInterval(autoTestInterval);
                autoTestInterval = null;
                document.getElementById('overlay-hint').innerText = "Tap to Cycle • ESC to Exit";
            }
        }
        // Core Overlay Logic
        function openOverlay(overlay) {
            overlay.style.display = 'block';
            if (document.documentElement.requestFullscreen) {
                document.documentElement.requestFullscreen();
            }
            const hint = document.getElementById('overlay-hint');
            hint.style.opacity = '1';
            clearTimeout(window.hintTimeout);
            window.hintTimeout = setTimeout(() => {
                hint.style.opacity = '0';
            }, 3000);
        }
        function cycleColor() {
            const overlay = document.getElementById('test-overlay');
            currentIndex = (currentIndex + 1) % sequence.length;
            overlay.style.background = sequence[currentIndex];
            const hint = document.getElementById('overlay-hint');
            hint.style.opacity = '1';
            clearTimeout(window.hintTimeout);
            window.hintTimeout = setTimeout(() => {
                hint.style.opacity = '0';
            }, 1500);
        }
        function handleOverlayClick() {
            if (autoTestInterval) {
                // If auto-test is running, user clicking means they want out
                stopTest();
            } else {
                cycleColor();
            }
        }
        function stopTest() {
            clearAutoTest();
            document.getElementById('test-overlay').style.display = 'none';
            if (document.fullscreenElement && document.exitFullscreen) {
                document.exitFullscreen();
            }
        }
        document.addEventListener('keydown', (e) => {
            if (e.key === 'Escape') stopTest();
            if (document.getElementById('test-overlay').style.display === 'block' && !autoTestInterval) {
                if (e.key === 'ArrowRight' || e.key === ' ') cycleColor();
                if (e.key === 'ArrowLeft') {
                    const overlay = document.getElementById('test-overlay');
                    currentIndex = (currentIndex - 1 + sequence.length) % sequence.length;
                    overlay.style.background = sequence[currentIndex];
                }
            }
        });
